DOMAIN1 = [{'num': 1, 'topic': 1, 'title': 'Establish a trace baseline', 'objective': 'LO1', 'desc': 'A capture is a measurement at one observation point, not a complete network history.', 'build': 'Evidence CSV and packet findings', 'services': 'Wireshark, TShark, Python', 'steps': [('Prepare your lab workspace. Open this lab folder in a terminal. Windows uses py -3 in place of python3. Wireshark GUI alone is sufficient for the investigation; CLI scripts require TShark on PATH. Run the fixture verification first.', 'python3 scripts/verify.py'), ('Open data/branch-office.pcap with File > Open. Clear the display filter. Record the packet count from the status bar and the capture duration from Statistics > Capture File Properties.', ''), ('Select frame 1. Expand Ethernet II and Address Resolution Protocol in Packet Details. Click the sender IP field and observe the corresponding bytes.', ''), ('Apply arp in the display filter toolbar. Compare request and reply sender/target IP and MAC addresses. Save the two frame numbers in outputs/findings.md.', ''), ('Export a reproducible packet table. Record the filter, frame numbers, measurement, explanation and limitation in outputs/findings.md.', 'python3 scripts/export_evidence.py')], 'test': 'The supplied arp expression matches 2 frame(s) in the specified capture. Run scripts/verify.py and compare the listed frame numbers. Keep your findings and exported table in outputs/. Explain the observed result rather than only copying a count.', 'troubleshooting': 'TShark not found: install Wireshark CLI tools and add the installation folder to PATH; on Windows use the Wireshark install directory. A filter returns zero: clear other filters, use the specified capture, and check the expression is in the display toolbar. TLS remains opaque: select the matching lab-tls.keys file by absolute path, reload, and remove a key-log preference from another lab.', 'reflection': 'Which second observation point would strengthen your conclusion?', 'challenge': 'Develop and explain an alternative filter.', 'duration': 45}]
